INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-1-1', 'CSIRKE ALAPLÉ', 'Chicken Stock', 2, 1, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Csirke farhát", "qty": "50 kg", "image": null, "enName": "Chicken back"}, {"id": "i1", "name": "Csirke láb", "qty": "10 kg", "image": null, "enName": "Chicken feet"}, {"id": "i2", "name": "csirke szárny kg     szeletelve", "qty": "10 kg", "image": null, "enName": "Chicken wings, sliced"}, {"id": "i3", "name": "Újhagyma", "qty": "5 kg", "image": null, "enName": "Spring onion"}, {"id": "i4", "name": "Répa pucolva kg     tisztitva", "qty": "3 kg", "image": null, "enName": "Carrot, peeled"}, {"id": "i5", "name": "szárítottshitake", "qty": "200 g", "image": null, "enName": "Dried shiitake mushroom"}, {"id": "i6", "name": "egész feherbors", "qty": "200 g", "image": null, "enName": "Whole white peppercorns"}, {"id": "i7", "name": "Víz", "qty": "200 l", "image": null, "enName": "Water"}]'::jsonb, '[{"id": "s0", "desc": "megtöltöm az üstöt csirkével és felforralom majd lemosom. Hozzádaom a zöldségets felforralom és kizárom.Hagyom állni egy estét.", "image": null, "enDesc": "Fill the pot with chicken and bring to a boil, then rinse. Add the vegetables, bring back to a boil, and seal. Leave to stand overnight."}, {"id": "s1", "desc": "Amikor kész másnap. LEszűrom gn-be. ki kell hűteni és csomagolni. Ezt követi a takarítás.", "image": null, "enDesc": "When ready the next day, strain into a GN tray. Cool and pack. Clean the equipment."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-1-2', 'CSIRKE ERŐLEVES', 'Chicken Consommé', 2, 1, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Csirke alaplé", "qty": "100 l", "image": null, "enName": "Chicken stock"}, {"id": "i1", "name": "Csirkemell", "qty": "10 kg", "image": null, "enName": "Chicken breast"}, {"id": "i2", "name": "japán szójaszósz", "qty": "3000 g", "image": null, "enName": "Japanese soy sauce"}, {"id": "i3", "name": "sárga kannás)", "qty": "500 g", "image": null, "enName": "Maggi seasoning (not yellow can)"}, {"id": "i4", "name": "cukor", "qty": "300 g", "image": null, "enName": "Sugar"}, {"id": "i5", "name": "Só", "qty": "500 g", "image": null, "enName": "Salt"}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-1-3', 'PÁLINKA ALAPLÉ', 'Pálinka Stock', 2, 1, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Csirkefarhát", "qty": "10 kg", "image": null, "enName": "Chicken back"}, {"id": "i1", "name": "Alaplé", "qty": "62200 g", "image": null, "enName": "Stock"}, {"id": "i2", "name": "Gyömbér", "qty": "1100 g", "image": null, "enName": "Ginger"}, {"id": "i3", "name": "Fokhagyma", "qty": "2300 g", "image": null, "enName": "Garlic"}, {"id": "i4", "name": "Kombu - algalevél", "qty": "690 g", "image": null, "enName": "Kombu seaweed"}, {"id": "i5", "name": "Só", "qty": "100 g", "image": null, "enName": "Salt"}, {"id": "i6", "name": "Dashipor", "qty": "115 g", "image": null, "enName": "Dashi powder"}, {"id": "i7", "name": "Goji", "qty": "210 g", "image": null, "enName": "Goji berries"}]'::jsonb, '[{"id": "s0", "desc": "Bukóüstben Blansírozd a csirkefarhátat. Mosd le, majd add hozzá a többi hozzávalót. Forrald össze.", "image": null, "enDesc": "In a steam pot, blanch the chicken back. Rinse, then add the remaining ingredients and bring to a boil."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-1-4', 'ALAPLE CSOMAG NEO', 'Neo Stock Pack', 2, 1, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "marha gombcsont", "qty": "30 kg", "image": null, "enName": "Beef knuckle bone"}, {"id": "i1", "name": "csirke farhat", "qty": "20 kg", "image": null, "enName": "Chicken back"}, {"id": "i2", "name": "csirke lab", "qty": "20 kg", "image": null, "enName": "Chicken feet"}, {"id": "i3", "name": "feherbors", "qty": "75 g", "image": null, "enName": "White peppercorns"}, {"id": "i4", "name": "csillaganizs", "qty": "15 db", "image": null, "enName": "Star anise"}, {"id": "i5", "name": "fekete kardamom", "qty": "45 db", "image": null, "enName": "Black cardamom"}, {"id": "i6", "name": "szaritott shiitake", "qty": "75 db", "image": null, "enName": "Dried shiitake"}, {"id": "i7", "name": "marha gombcsont", "qty": "2 kg", "image": null, "enName": "Beef knuckle bone"}, {"id": "i8", "name": "farhat", "qty": "1 kg", "image": null, "enName": "Chicken back"}, {"id": "i9", "name": "csirke lab", "qty": "1 kg", "image": null, "enName": "Chicken feet"}, {"id": "i10", "name": "feherbors", "qty": "5 g", "image": null, "enName": "White peppercorns"}, {"id": "i11", "name": "csillaganizs", "qty": "1 db", "image": null, "enName": "Star anise"}, {"id": "i12", "name": "fekete kardamom", "qty": "3 db", "image": null, "enName": "Black cardamom"}, {"id": "i13", "name": "szaritott shiitake", "qty": "5 db", "image": null, "enName": "Dried shiitake"}]'::jsonb, '[{"id": "s0", "desc": "Külön külön forrázom, mosom. Azta összerakom egy zacsiba.Fagyasztom. 1 A marha csontot tedd fel hideg vizben, es forrald fel a vizet, amint felforrt, hagyd meg foni 2-3 percet, majd hideg viz alatt oblitsd le.", "image": null, "enDesc": "Blanch and rinse each separately. Then combine in a vacuum bag and freeze."}, {"id": "s1", "desc": "2 A csirke farhatat es labat szinten ugyanigy blansirozd le. 3 Merd ossze a csontokat es a fuszereket egy vakuum zsakba, es alacsony vakuumon csomagold el, majd fagyasztva tarold.", "image": null, "enDesc": "Blanch and rinse the chicken back and feet separately. Weigh the bones and spices into a vacuum bag."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-1-5', 'Neo alaplé', 'Neo Stock', 2, 1, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "marha gombcsont", "qty": "2 kg", "image": null, "enName": "Beef knuckle bone"}, {"id": "i1", "name": "farhat", "qty": "1 kg", "image": null, "enName": "Chicken back"}, {"id": "i2", "name": "csirke lab", "qty": "1 kg", "image": null, "enName": "Chicken feet"}, {"id": "i3", "name": "feherbors", "qty": "5 g", "image": null, "enName": "White peppercorns"}, {"id": "i4", "name": "csillaganizs", "qty": "1 db", "image": null, "enName": "Star anise"}, {"id": "i5", "name": "fekete kardamom", "qty": "3 db", "image": null, "enName": "Black cardamom"}, {"id": "i6", "name": "szaritott shiitake", "qty": "5 db", "image": null, "enName": "Dried shiitake"}, {"id": "i7", "name": "fokhagyma", "qty": "100 g", "image": null, "enName": "Garlic"}, {"id": "i8", "name": "újhagyma", "qty": "80 g", "image": null, "enName": "Spring onion"}, {"id": "i9", "name": "vöröshagyma tisztítva", "qty": "300 g", "image": null, "enName": "Onion, peeled"}, {"id": "i10", "name": "gyömbér", "qty": "200 g", "image": null, "enName": "Ginger"}, {"id": "i11", "name": "víz", "qty": "20 kg", "image": null, "enName": "Water"}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-2-1', 'CSIRKE SZÓSZ', 'Chicken Sauce', 0, 2, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Alaplé", "qty": "40 L", "image": null, "enName": "Stock"}, {"id": "i1", "name": "Japán szójaszósz", "qty": "14.4 kg", "image": null, "enName": "Japanese soy sauce"}, {"id": "i2", "name": "Mirin", "qty": "8.4 kg", "image": null, "enName": "Mirin"}, {"id": "i3", "name": "cukor", "qty": "3.1 kg", "image": null, "enName": "Sugar"}, {"id": "i4", "name": "Csirke zsír", "qty": "6 kg", "image": null, "enName": "Chicken fat"}, {"id": "i5", "name": "msg", "qty": "0.5 kg", "image": null, "enName": "MSG"}, {"id": "i6", "name": "alaplé", "qty": "8 l", "image": null, "enName": "Stock"}, {"id": "i7", "name": "kukorica keményitő", "qty": "2.2 kg", "image": null, "enName": "Cornstarch"}]'::jsonb, '[{"id": "s0", "desc": "Ide sült csirkezsír kell. Ha nincs akkor jó a szűz. 1./ Az alaplevet, a szójaszószt, a mirint, az msgt, a csirkezsírt és a cukrot forrald fel.", "image": null, "enDesc": "Use rendered chicken fat. If unavailable, neutral oil works. Combine the stock, soy sauce, mirin, MSG, and chicken fat and bring to a boil."}, {"id": "s1", "desc": "2./Sűrítsd be egy kukoricalisztes alapleves mixxel ami a recept also felen szerepel. A keményítőhöz hideg legyen az alaplé.", "image": null, "enDesc": "Thicken with a cornstarch slurry using cold stock. See bottom of recipe for ratio."}, {"id": "s2", "desc": "3./Sűrítés után forralom egy kicsit 15 percet, hogy ne legyen keményítő íze. utána GN és hűtő vagy sokkoló.", "image": null, "enDesc": "After thickening, simmer for 15 minutes to cook out the starch taste, then transfer to GN tray and blast-chill or refrigerate."}, {"id": "s3", "desc": "2 Sokkold le 3c fokra majd 2.5kgnként vákuumozd le. Sokkolva fagyaszd a vákuum zsákokat. Fagyasztva 6 hónapig tárolható.", "image": null, "enDesc": "Blast-chill to 3°C, then vacuum-pack in 2.5 kg portions and freeze. Keeps frozen for 6 months."}, {"id": "s4", "desc": "Ha nem fagyasztod le akkor használd fel 5 napon belül. Kiolvasztva 3 napon belül el kell használni.", "image": null, "enDesc": "If not freezing, use within 5 days. After thawing, use within 3 days."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-2-2', 'Csirke marinád Shou Pa', 'Shou Pa Chicken Marinade', 0, 2, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Sárga chilli paszta", "qty": "6000 g", "image": null, "enName": "Yellow chilli paste"}, {"id": "i1", "name": "tisztított fokhagyma", "qty": "900 g", "image": null, "enName": "Garlic, peeled"}, {"id": "i2", "name": "Citromlé", "qty": "4000 g", "image": null, "enName": "Lemon juice"}, {"id": "i3", "name": "olaj- fritu v. repce", "qty": "8000 g", "image": null, "enName": "Neutral oil (frying or rapeseed)"}, {"id": "i4", "name": "Citromhéj", "qty": "200 g", "image": null, "enName": "Lemon zest"}, {"id": "i5", "name": "citromnád", "qty": "1000 g", "image": null, "enName": "Lemongrass"}, {"id": "i6", "name": "Répa pucolva", "qty": "6000 g", "image": null, "enName": "Carrot, peeled"}, {"id": "i7", "name": "Tamarind paszta", "qty": "4500 g", "image": null, "enName": "Tamarind paste"}]'::jsonb, '[{"id": "s0", "desc": "1550 g met annyi kell 10 kg csirkéhez 1 A répát mosd és hámozd meg, majd vágd 1 x 1cm kockákra. 2 Mérd ki az összes többi hozzávvalót egy nagy dobozba és add hozzá a répát.", "image": null, "enDesc": "Weigh — this amount is for 10 kg chicken. Wash and peel the carrot, cut into 1×1 cm cubes."}, {"id": "s1", "desc": "3 Keverd el az összes alapanyagot és kisebb adagokban a thermomix legmagasabb fokozatán turmixold simára.", "image": null, "enDesc": "Weigh all ingredients and blend in a Thermomix on the highest setting in small batches until smooth."}, {"id": "s2", "desc": "Soha ne töltsd túl a thermixet! Mindig csak maximum a feléig. Nem szabad darbosnak lennie, ezért a turmixban át kell turmixolni.", "image": null, "enDesc": "Never overfill the Thermomix — maximum half-full. Blend until completely smooth."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-2-3', 'Tigris/PopCorn Marinád', 'Tiger / Popcorn Chicken Marinade', 0, 2, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "shaoxing", "qty": "8 kg", "image": null, "enName": "Shaoxing wine"}, {"id": "i1", "name": "so", "qty": "400 g", "image": null, "enName": "Salt"}, {"id": "i2", "name": "tisztitott fokhagyma", "qty": "400 g", "image": null, "enName": "Garlic, peeled"}, {"id": "i3", "name": "cukor", "qty": "300 g", "image": null, "enName": "Sugar"}, {"id": "i4", "name": "msg", "qty": "200 g", "image": null, "enName": "MSG"}, {"id": "i5", "name": "feherbors", "qty": "50 g", "image": null, "enName": "White pepper"}, {"id": "i6", "name": "szezámolaj", "qty": "250 g", "image": null, "enName": "Sesame oil"}, {"id": "i7", "name": "csirke mell szeletek", "qty": "3 kg", "image": null, "enName": "Chicken breast slices"}, {"id": "i8", "name": "marinad", "qty": "0.5 kg", "image": null, "enName": "Marinade"}]'::jsonb, '[{"id": "s0", "desc": "A shaoxing kívül bele teszem turmixba. feltöltöm annyi shaoxinnal ami belefér. AMi kimaradt azzal kiöblítem a turmixot. elkeverem habverővel.", "image": null, "enDesc": "Add everything except the shaoxing to the blender. Top up with enough shaoxing to fill. Use any leftover shaoxing to rinse the blender."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
