INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-2-6', 'SAN BEI SZÓSZ', 'San Bei Sauce', 0, 2, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "ALAPANYAGOK", "qty": "200 liter", "image": null, "enName": "Ingredients"}, {"id": "i1", "name": "Sötét szójaszósz", "qty": "13.9 kg", "image": null, "enName": "Dark soy sauce"}, {"id": "i2", "name": "Világos szójaszósz", "qty": "36.1 kg", "image": null, "enName": "Light soy sauce"}, {"id": "i3", "name": "Szűrt víz", "qty": "27.8 kg", "image": null, "enName": "Filtered water"}, {"id": "i4", "name": "Rizsecet", "qty": "34.8 kg", "image": null, "enName": "Rice vinegar"}, {"id": "i5", "name": "Shaoxing főzőbor", "qty": "41.7 kg", "image": null, "enName": "Shaoxing cooking wine"}, {"id": "i6", "name": "Cukor", "qty": "18.3 kg", "image": null, "enName": "Sugar"}, {"id": "i7", "name": "Mirin", "qty": "16.7 kg", "image": null, "enName": "Mirin"}, {"id": "i8", "name": "msg", "qty": "700 g", "image": null, "enName": "MSG"}, {"id": "i9", "name": "ribonukleotid", "qty": "70 g", "image": null, "enName": "Ribonucleotide"}, {"id": "i10", "name": "Újhagyma fokhagyma felezve", "qty": "5 kg", "image": null, "enName": "Spring onion and garlic, halved"}, {"id": "i11", "name": "hájasan", "qty": "25 kg", "image": null, "enName": "With fat on"}, {"id": "i12", "name": "héjasan", "qty": "25 kg", "image": null, "enName": "With skin on"}]'::jsonb, '[{"id": "s0", "desc": "1./ A mosott gyömbért vágd fel durva darabokra. 20 liter sütőolajon süsd le a bukóüstben. 2./ A fokhagymát keresztben vágd félre, és akárcsak a gyömbért pirítsd meg a bukóüstben.", "image": null, "enDesc": "Chop the washed ginger roughly. Fry in 20 litres of oil in the steam pot."}, {"id": "s1", "desc": "3./ Mindent hozzáadok, felforralom és lezárom hagyom állni egy napot. 4./ Másnap: fekete szűrővel leszűröm, kihűtöm - sokkolom majd csomagolom. !!!", "image": null, "enDesc": "Halve the garlic crosswise. Add all remaining ingredients, bring to a boil, seal and leave to stand for one day."}, {"id": "s2", "desc": "Ami marad a gyömbér sütésután azt elteszed seucsuani chili olajnak.", "image": null, "enDesc": "Everything added, bring to a boil and seal, leave to stand one day. Next day: strain through a fine sieve, cool — done."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-2-7', 'GM SAN BEI SZÓSZ', 'GM San Bei Sauce', 0, 2, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "ALAPANYAGOK", "qty": "100 liter", "image": null, "enName": "Ingredients"}, {"id": "i1", "name": "szójaszósz", "qty": "21,6 kg", "image": null, "enName": "Soy sauce"}, {"id": "i2", "name": "Szűrt víz", "qty": "10,8 kg", "image": null, "enName": "Filtered water"}, {"id": "i3", "name": "GM Rizsecet / zöld", "qty": "10,8 kg", "image": null, "enName": "GM Rice vinegar (green)"}, {"id": "i4", "name": "Sake", "qty": "16,2 kg", "image": null, "enName": "Sake"}, {"id": "i5", "name": "Cukor", "qty": "7,2 kg", "image": null, "enName": "Sugar"}, {"id": "i6", "name": "GM Mirin", "qty": "6,5 kg", "image": null, "enName": "GM Mirin"}, {"id": "i7", "name": "msg", "qty": "270 g", "image": null, "enName": "MSG"}, {"id": "i8", "name": "ribonukleotid", "qty": "27 g", "image": null, "enName": "Ribonucleotide"}, {"id": "i9", "name": "Újhagyma fokhagyma felezve", "qty": "2 kg", "image": null, "enName": "Spring onion and garlic, halved"}, {"id": "i10", "name": "hájasan", "qty": "10 kg", "image": null, "enName": "With fat on"}, {"id": "i11", "name": "héjasan", "qty": "10 kg", "image": null, "enName": "With skin on"}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-2-8', 'BORSMÁRTÁS', 'Black Pepper Sauce', 0, 2, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Marha faggyú", "qty": "5600 g", "image": null, "enName": "Beef tallow"}, {"id": "i1", "name": "finomra vágott hagyma", "qty": "8000 g", "image": null, "enName": "Onion, finely chopped"}, {"id": "i2", "name": "tisztitott fokhagyma", "qty": "800 g", "image": null, "enName": "Garlic, peeled"}, {"id": "i3", "name": "Tört feketebors", "qty": "1200 g", "image": null, "enName": "Cracked black pepper"}, {"id": "i4", "name": "Sötét szójaszósz", "qty": "4800 g", "image": null, "enName": "Dark soy sauce"}, {"id": "i5", "name": "maggi sárga flakonos", "qty": "800 g", "image": null, "enName": "Maggi (yellow bottle)"}, {"id": "i6", "name": "Osztrigaszósz konzerv", "qty": "8400 g", "image": null, "enName": "Oyster sauce (canned)"}, {"id": "i7", "name": "Méz", "qty": "4800 g", "image": null, "enName": "Honey"}, {"id": "i8", "name": "Marha alaplé", "qty": "35000 g", "image": null, "enName": "Beef stock"}, {"id": "i9", "name": "Chinkiang ecet", "qty": "1600 g", "image": null, "enName": "Chinkiang vinegar"}, {"id": "i10", "name": "só", "qty": "200 g", "image": null, "enName": "Salt"}, {"id": "i11", "name": "csirke alaplé", "qty": "5000 g", "image": null, "enName": "Chicken stock"}, {"id": "i12", "name": "kukorica keményítő", "qty": "2200 g", "image": null, "enName": "Cornstarch"}]'::jsonb, '[{"id": "s0", "desc": "​ Kiolvasztom a faggyút.", "image": null, "enDesc": "Melt the beef tallow."}, {"id": "s1", "desc": "​ Hozzáadom a vörös hagymát és karamelizálom.", "image": null, "enDesc": "Add the onion and caramelise."}, {"id": "s2", "desc": "​ Fokhagyma és tört bors. Fokhagymát turmixolom a mixerben olajjal. 4 Add hozzá a tobbi alapanyagot és forrald fel. Sűrítsd be kukorica keményítővel annyira hogy a zsiradék és a folyadék emulziót alkosson. Hűtsd le a sokkolóban. Vákuumozd le es tárold a mélyhűtőben felhasználásig.", "image": null, "enDesc": "Add garlic and cracked pepper. Blend the garlic in a mixer with oil. Add remaining ingredients and bring to a boil. Thicken with a cornstarch slurry."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-2-9', 'Red Braise', 'Red Braise Sauce', 0, 2, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Marha faggyu", "qty": "3 kg", "image": null, "enName": "Beef tallow"}, {"id": "i1", "name": "gyomber", "qty": "3 kg", "image": null, "enName": "Ginger"}, {"id": "i2", "name": "Ujhagyma", "qty": "1 kg", "image": null, "enName": "Spring onion"}, {"id": "i3", "name": "vöröshagyma tisztított kockázva", "qty": "6 kg", "image": null, "enName": "Onion, peeled and diced"}, {"id": "i4", "name": "Fokhagyma tisztított", "qty": "600 g", "image": null, "enName": "Garlic, peeled"}, {"id": "i5", "name": "Tobanjan", "qty": "600 g", "image": null, "enName": "Tobanjan (doubanjiang)"}, {"id": "i6", "name": "Paradicsom pure - sűrített", "qty": "1500 g", "image": null, "enName": "Tomato purée (concentrated)"}, {"id": "i7", "name": "Paradicsom konzerv - darabos", "qty": "15 kg", "image": null, "enName": "Tinned tomatoes (chopped)"}, {"id": "i8", "name": "Vilagos szojaszosz", "qty": "2400 g", "image": null, "enName": "Light soy sauce"}, {"id": "i9", "name": "So", "qty": "1290 g", "image": null, "enName": "Salt"}, {"id": "i10", "name": "Garum por", "qty": "600 g", "image": null, "enName": "Garum powder"}, {"id": "i11", "name": "shaoxin", "qty": "1350 g", "image": null, "enName": "Shaoxing wine"}, {"id": "i12", "name": "Fermentalt feketebab", "qty": "750 g", "image": null, "enName": "Fermented black beans"}, {"id": "i13", "name": "Cukor", "qty": "1500 g", "image": null, "enName": "Sugar"}, {"id": "i14", "name": "Sarga bab paszta", "qty": "900 g", "image": null, "enName": "Yellow bean paste"}, {"id": "i15", "name": "Osztriga szosz", "qty": "1500 g", "image": null, "enName": "Oyster sauce"}, {"id": "i16", "name": "Baberlevel", "qty": "30 g", "image": null, "enName": "Bay leaf"}, {"id": "i17", "name": "Msg", "qty": "90 g", "image": null, "enName": "MSG"}]'::jsonb, '[{"id": "s0", "desc": "1./ A zoldsegeket apritsd fel durvara es a marhafaggyun (az alaplebol lesz boven) kezd el piritani. Alacsony hofokon folyamatos kevergetes mellett amig egyenletesen nem karamellizalodnak ugy 20-30 perc. ujhagyma, fokhagyma, vöröshagyma, gyömbér egyszerre megy be pirtíani.", "image": null, "enDesc": "Roughly chop the vegetables and begin frying in beef tallow from the stock on a low heat, stirring continuously."}, {"id": "s1", "desc": "2./ Add hozza tobanjant es a paradicsom puret es fozd tovabbi 5percig. 3./ Add hozza a maradek hozzavalokat.", "image": null, "enDesc": "Add the tobanjan and tomato purée and cook for a further 5 minutes. Add remaining ingredients."}, {"id": "s2", "desc": "Itt kell hozzáadni a Paradicsom konzerv - darabos. 4./ A baberlevelet vedd ki turmixolás előtt. rakd a legnagyobb szurobe es szurot rakd a red braisebe es a vegen emeld ki a baberlevelet.", "image": null, "enDesc": "Add the tinned tomatoes at this point. Remove the bay leaf before blending. Pass through the largest sieve."}, {"id": "s3", "desc": "5./ Fozd 40-50 percig alacsony langon folyamatos kevergetes mellett.", "image": null, "enDesc": "Cook on a low heat for 40–50 minutes with continuous stirring."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-2-10', 'MAPO TOFU', 'Mapo Tofu Sauce', 0, 2, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "repce olaj kg   hagyma", "qty": "2880 g", "image": null, "enName": "Rapeseed oil + onion"}, {"id": "i1", "name": "Gyömbér finomra vágva g   finomra vágva", "qty": "600 g", "image": null, "enName": "Ginger, finely chopped + finely chopped"}, {"id": "i2", "name": "Tobanjan", "qty": "5050 g", "image": null, "enName": "Tobanjan"}, {"id": "i3", "name": "Szűrt víz", "qty": "28 kg", "image": null, "enName": "Filtered water"}, {"id": "i4", "name": "Kínai gomba por", "qty": "180 g", "image": null, "enName": "Chinese mushroom powder"}, {"id": "i5", "name": "Világos szójaszósz", "qty": "4010 g", "image": null, "enName": "Light soy sauce"}, {"id": "i6", "name": "Cukor", "qty": "870 g", "image": null, "enName": "Sugar"}, {"id": "i7", "name": "Shaoxin főzőbor", "qty": "2050 g", "image": null, "enName": "Shaoxing cooking wine"}, {"id": "i8", "name": "bolti szecsuáni olaj", "qty": "240 g", "image": null, "enName": "Shop-bought Sichuan oil"}, {"id": "i9", "name": "víz", "qty": "2.8 l", "image": null, "enName": "Water"}, {"id": "i10", "name": "Kukoricakeményítő", "qty": "1400 g", "image": null, "enName": "Cornstarch"}]'::jsonb, '[{"id": "s0", "desc": "1./ A kockázott hagymát és az olajat öntsd a bukoustbe és alaposan keverd össze. 2./ Parold uvegesre.", "image": null, "enDesc": "Pour the diced onion and oil into the steam pot and mix thoroughly. Sweat until translucent."}, {"id": "s1", "desc": "3./ Add az olajos hagymához a fokhagymát, a gyömbért és a tobanjant és alacsony fokozaton folyamatos kevergetés közben párold még 10-12 percig.", "image": null, "enDesc": "Add the garlic, ginger, and tobanjan to the oily onion base and fry on a low setting with continuous stirring."}, {"id": "s2", "desc": "4./ Öntsd fel a szűrt vízzel, a szójaszósszal, gombaporral, és add hozzá a cukrot, a főzőbort illetve a bolti szecsuáni olajat.", "image": null, "enDesc": "Add the filtered water, soy sauce, mushroom powder, sugar, cooking wine, and shop-bought Sichuan oil. Bring to a boil."}, {"id": "s3", "desc": "Kapcsold nagy fokozatra és forrald fel. 5./ A keményítőt alaposan keverd el a maradék vízzel (az anyaghányados lista alsó részén), úgy hogy csomómentes legyen. folyamatosan keverve vékony sugárban öntsd a forrásban lévő mapo alaphoz.", "image": null, "enDesc": "Stir the cornstarch well into the remaining water (see ratio at the bottom of the recipe list). Thicken by pouring into the boiling mapo."}, {"id": "s4", "desc": "Forrald fel újra a mapot és alacsony lángon forrald 2-3 percig amíg szép fényes és sűrű nem lesz a keményítőtől.", "image": null, "enDesc": "Bring to a boil again, then simmer on a low heat for 2–3 minutes until the sauce is glossy and thick from the starch."}, {"id": "s5", "desc": "Habverővel sűrítés 6./ Öntsd át egy mély gasztronormba és rakd a sokkolóba. Rakd bele a maghőmérőt és sokkold le 3C-ra.", "image": null, "enDesc": "Pour into a deep gastronorm tray, place in the blast chiller with a probe and chill to 3°C."}, {"id": "s6", "desc": "Amint lehűlt vákuumozd le 2.5kg-ként, és sokkolva fagyaszd le. Sokkolva fagyasztva 3 hónapig tárolható, olvasztás után 5 nap az eltarthatósági ideje.", "image": null, "enDesc": "Once chilled, vacuum-pack in 2.5 kg portions and blast-freeze. Keeps blast-frozen for 3 months, and 5 days after thawing."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-2-11', 'TONKATSU SZOSZ', 'Tonkatsu Sauce', 0, 2, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "darabolva", "qty": "6000 g", "image": null, "enName": "Chopped"}, {"id": "i1", "name": "vörös hagyma durva kockara vagva", "qty": "1000 g", "image": null, "enName": "Onion, roughly diced"}, {"id": "i2", "name": "pucolt repa durvara vagva", "qty": "1000 g", "image": null, "enName": "Carrot, roughly chopped"}, {"id": "i3", "name": "szárzeller durvara vagva", "qty": "400 g", "image": null, "enName": "Celery, roughly chopped"}, {"id": "i4", "name": "gyomber tisztítva", "qty": "200 g", "image": null, "enName": "Ginger, peeled"}, {"id": "i5", "name": "tisztított fokhagyma", "qty": "100 g", "image": null, "enName": "Garlic, peeled"}, {"id": "i6", "name": "ketchup-Heinz", "qty": "4000 g", "image": null, "enName": "Heinz ketchup"}, {"id": "i7", "name": "baracklekvar - sargabarck dzsem extra", "qty": "4000 g", "image": null, "enName": "Apricot jam (extra)"}, {"id": "i8", "name": "vilagos szojaszosz", "qty": "3000 g", "image": null, "enName": "Light soy sauce"}, {"id": "i9", "name": "maltoz", "qty": "2000 g", "image": null, "enName": "Maltose"}, {"id": "i10", "name": "rizsecet - suehiro / japán", "qty": "2000 g", "image": null, "enName": "Rice vinegar (Suehiro / Japanese)"}, {"id": "i11", "name": "chinkiang ecet", "qty": "2000 g", "image": null, "enName": "Chinkiang vinegar"}, {"id": "i12", "name": "hoisin szosz", "qty": "800 g", "image": null, "enName": "Hoisin sauce"}, {"id": "i13", "name": "sotet szojaszosz", "qty": "800 g", "image": null, "enName": "Dark soy sauce"}, {"id": "i14", "name": "maggi - sárga flakon", "qty": "1000 g", "image": null, "enName": "Maggi (yellow bottle)"}, {"id": "i15", "name": "citromsav", "qty": "90 g", "image": null, "enName": "Citric acid"}, {"id": "i16", "name": "so", "qty": "100 g", "image": null, "enName": "Salt"}, {"id": "i17", "name": "msg", "qty": "40 g", "image": null, "enName": "MSG"}, {"id": "i18", "name": "xantan", "qty": "4 g", "image": null, "enName": "Xanthan gum"}, {"id": "i19", "name": "baberlevel", "qty": "5 g", "image": null, "enName": "Bay leaf"}, {"id": "i20", "name": "szegfubors", "qty": "25 g", "image": null, "enName": "Allspice"}, {"id": "i21", "name": "szegfuszeg őrölt", "qty": "5 g", "image": null, "enName": "Ground cloves"}, {"id": "i22", "name": "cassia - fahéj ázsiai típus", "qty": "23 g", "image": null, "enName": "Cassia (Asian-style cinnamon)"}, {"id": "i23", "name": "szaritott zsalya", "qty": "5 g", "image": null, "enName": "Dried sage"}, {"id": "i24", "name": "szaritott kakukkfu", "qty": "5 g", "image": null, "enName": "Dried thyme"}, {"id": "i25", "name": "szaritott oregano", "qty": "5 g", "image": null, "enName": "Dried oregano"}, {"id": "i26", "name": "anizsmag - helyette édeskömény", "qty": "13 g", "image": null, "enName": "Anise seed (or fennel as substitute)"}]'::jsonb, '[{"id": "s0", "desc": "1./ A zoldsegeket pucold meg, es kockazd fel kozel azonos mereture, a gyomber es a fokhagyma mehet kicsit kisebbre, merd ki es rakd perforalt 1/1-es talcakra.", "image": null, "enDesc": "Peel the vegetables and cut into roughly equal pieces; ginger and garlic can be slightly smaller. Weigh all ingredients."}, {"id": "s1", "desc": "1 Gn alma. Az Össze többi 3 gn-re. 2./ 25 perc alatt 100 C gozon fozd puhara mind.", "image": null, "enDesc": "1 GN apple. All remaining ingredients into 3 GN trays. Steam at 100°C for 25 minutes until soft."}, {"id": "s2", "desc": "3./ A fűszereket le kell porítani mixerben. 4./ Mindent tegyél bele bukóüstvbe. Forrald fel, majd turmixold el a nagy botmixerrel es kozben adagold hozza a xantant.", "image": null, "enDesc": "Grind the spices to a powder in a blender."}, {"id": "s3", "desc": "5./ Átturmixol vitamixerben.", "image": null, "enDesc": "Combine everything in a steam pot. Bring to a boil, then blend with a large stick blender."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-2-12', 'SHA CHA CSIRKELÁB szósz', 'Sha Cha Chicken Feet Sauce', 0, 2, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Csirkeláb", "qty": "10 kg", "image": null, "enName": "Chicken feet"}, {"id": "i1", "name": "Shaoxin főzőbor", "qty": "3000 g", "image": null, "enName": "Shaoxing cooking wine"}, {"id": "i2", "name": "Víz", "qty": "30 l", "image": null, "enName": "Water"}, {"id": "i3", "name": "Só", "qty": "100 g", "image": null, "enName": "Salt"}, {"id": "i4", "name": "cukor", "qty": "100 g", "image": null, "enName": "Sugar"}, {"id": "i5", "name": "Csillagánizs", "qty": "10 db", "image": null, "enName": "Star anise"}, {"id": "i6", "name": "Fahéj", "qty": "10 db", "image": null, "enName": "Cinnamon"}, {"id": "i7", "name": "vágott", "qty": "1000 g", "image": null, "enName": "Chopped"}, {"id": "i8", "name": "felezett", "qty": "1000 g", "image": null, "enName": "Halved"}, {"id": "i9", "name": "Újhagyma", "qty": "1000 g", "image": null, "enName": "Spring onion"}]'::jsonb, '[{"id": "s0", "desc": "A csirkelábat tisztítsd meg, vágd le a körmöket, majd alaposan masszírozd be sóval. 30 perc után folyó víz alatt öblítsd le.", "image": null, "enDesc": "Clean the chicken feet, trim the nails, then massage thoroughly with salt. After 30 minutes, rinse under running water."}, {"id": "s1", "desc": "Rakj fel forrni mindent a bukóüstbe. 3 L vizet ízesítsd gyömbérrel, csillag ánizzsal, újhagymával, fahéjjal, fokhagymával, sóval és főzőborral. (Gondolkodtam főzés helyett a vákumzacskós gőzölésen.) Kb 30-40 perc alatt puhulásig kell főzni.", "image": null, "enDesc": "Place everything in the steam pot and bring to a boil. Season the water with ginger, star anise, spring onion, cinnamon, and garlic."}, {"id": "s2", "desc": "Ha elkészült a léből kivéve sokkoljuk őket.", "image": null, "enDesc": "Once cooked, remove from the liquid and blast-chill."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
