INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-3-1', 'LU RO FAN', 'Lu Rou Fan (Braised Pork Rice)', 0, 3, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "hoz", "qty": "100 kg", "image": null, "enName": "Water (to cover)"}, {"id": "i1", "name": "Sertés császár", "qty": "100 kg", "image": null, "enName": "Pork belly"}, {"id": "i2", "name": "Világos szójaszósz", "qty": "9600 g", "image": null, "enName": "Light soy sauce"}, {"id": "i3", "name": "Sötét szójaszósz", "qty": "8400 g", "image": null, "enName": "Dark soy sauce"}, {"id": "i4", "name": "Shaoxing főzőbor", "qty": "12000 g", "image": null, "enName": "Shaoxing cooking wine"}, {"id": "i5", "name": "Újhagyma", "qty": "800 g", "image": null, "enName": "Spring onion"}, {"id": "i6", "name": "felezve", "qty": "1600 g", "image": null, "enName": "Halved"}, {"id": "i7", "name": "Gyömbér héjastul vágva", "qty": "4000 g", "image": null, "enName": "Ginger with skin, chopped"}, {"id": "i8", "name": "fermentált vörös tofu", "qty": "2933 g", "image": null, "enName": "Fermented red tofu"}, {"id": "i9", "name": "Csillagánizs", "qty": "400 g", "image": null, "enName": "Star anise"}, {"id": "i10", "name": "Cukor", "qty": "3600 g", "image": null, "enName": "Sugar"}, {"id": "i11", "name": "Msg", "qty": "800 g", "image": null, "enName": "MSG"}, {"id": "i12", "name": "Egész szárított chilli", "qty": "533 g", "image": null, "enName": "Whole dried chilli"}, {"id": "i13", "name": "Fahéj kínai", "qty": "667 g", "image": null, "enName": "Chinese cinnamon"}]'::jsonb, '[{"id": "s0", "desc": "1 A sertés császárt olvaszd ki a hűtőben 24 alatt. 2 Vágd a császárt keresztben 8,5 cm vastag csíkokra.", "image": null, "enDesc": "Thaw the pork belly in the refrigerator for 24 hours. Cut into 8.5 cm wide strips crosswise."}, {"id": "s1", "desc": "3./ Bele tesszük a folyadékot. KÉszítünk egy fűszerzsákot és zöldségeket.Ami a tetejére kerül. 4./ Leforrázzuk a bukó üstben 50 kg-ként.", "image": null, "enDesc": "Add the liquid to the pot. Prepare a spice bag and vegetables for the top. Blanch in the steam pot."}, {"id": "s2", "desc": "Lemossuk és bele teszünk 100 kg-ot a 200 literes üstbe. Annyi vizet adunk hozzá, hogy ellepje a sertéshúst.", "image": null, "enDesc": "Rinse and place 100 kg into the 200-litre pot. Add enough water to cover the pork."}, {"id": "s3", "desc": "5./ FElforraljuk és hagyjuk másnapig állni. 6./ Másnap kiszedjük lehűtjük és csomagoljuk. Majd ismét 100 kg-ot felteszünk.", "image": null, "enDesc": "Bring to a boil and leave to stand until the next day. Next day, remove, cool and pack. Then load another 100 kg."}, {"id": "s4", "desc": "7./ HA a Lu rot el akarom csomagolni, akkor:a szószt vissza kell sűríteni, mert szét van vizezve. Egyébkénr le kell szűrni.", "image": null, "enDesc": "If packing the Lu Ro, the sauce must be reduced back down as it will have been diluted. Otherwise strain, chill and pack."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-3-2', 'LU WEI KACSACOMB', 'Lu Wei Duck Leg', 0, 3, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Sertés császár", "qty": "100 kg", "image": null, "enName": "Pork belly"}, {"id": "i1", "name": "Világos szójaszósz", "qty": "9600 g", "image": null, "enName": "Light soy sauce"}, {"id": "i2", "name": "Sötét szójaszósz", "qty": "8400 g", "image": null, "enName": "Dark soy sauce"}, {"id": "i3", "name": "Shaoxing főzőbor", "qty": "12000 g", "image": null, "enName": "Shaoxing cooking wine"}, {"id": "i4", "name": "Újhagyma", "qty": "800 g", "image": null, "enName": "Spring onion"}, {"id": "i5", "name": "felezve", "qty": "1600 g", "image": null, "enName": "Halved"}, {"id": "i6", "name": "Gyömbér héjastul vágva", "qty": "4000 g", "image": null, "enName": "Ginger with skin, chopped"}, {"id": "i7", "name": "fermentált vörös tofu", "qty": "2933 g", "image": null, "enName": "Fermented red tofu"}, {"id": "i8", "name": "Csillagánizs", "qty": "400 g", "image": null, "enName": "Star anise"}, {"id": "i9", "name": "Cukor", "qty": "3600 g", "image": null, "enName": "Sugar"}, {"id": "i10", "name": "Msg", "qty": "800 g", "image": null, "enName": "MSG"}, {"id": "i11", "name": "Egész szárított chilli", "qty": "533 g", "image": null, "enName": "Whole dried chilli"}, {"id": "i12", "name": "Fahéj", "qty": "667 g", "image": null, "enName": "Cinnamon"}, {"id": "i13", "name": "Nyers kacsacomb", "qty": "100 kg", "image": null, "enName": "Raw duck leg"}, {"id": "i14", "name": "Világos szójaszósz", "qty": "5760 g", "image": null, "enName": "Light soy sauce"}, {"id": "i15", "name": "Sötét szójaszósz", "qty": "5040 g", "image": null, "enName": "Dark soy sauce"}, {"id": "i16", "name": "Shaoxing főzőbor", "qty": "7200 g", "image": null, "enName": "Shaoxing cooking wine"}, {"id": "i17", "name": "Újhagyma", "qty": "480 g", "image": null, "enName": "Spring onion"}, {"id": "i18", "name": "Fokhagyma héjastul felezve", "qty": "400 g", "image": null, "enName": "Garlic with skin, halved"}, {"id": "i19", "name": "Gyömbér héjastul vágva", "qty": "2400 g", "image": null, "enName": "Ginger with skin, chopped"}, {"id": "i20", "name": "zöld szecsuáni bors", "qty": "80 g", "image": null, "enName": "Green Sichuan pepper"}, {"id": "i21", "name": "Csillagánizs", "qty": "160 g", "image": null, "enName": "Star anise"}, {"id": "i22", "name": "Cukor", "qty": "2160 g", "image": null, "enName": "Sugar"}, {"id": "i23", "name": "Msg", "qty": "480 g", "image": null, "enName": "MSG"}, {"id": "i24", "name": "Egész szárított chilli", "qty": "320 g", "image": null, "enName": "Whole dried chilli"}, {"id": "i25", "name": "Fahéj", "qty": "400 g", "image": null, "enName": "Cinnamon"}]'::jsonb, '[{"id": "s0", "desc": "1./ bele rakjuk az üstbe. FElforralom és másnap kiveszem. 2./ Tépkedjük és félreteszünk neki szószt és felöntjük majd csomagoljuk.", "image": null, "enDesc": "Place in the pot. Bring to a boil and remove the next day. Shred and set aside with sauce, top up and pack."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-3-3', 'Tigris csirke', 'Tiger Chicken', 0, 3, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "shaoxing", "qty": "8 kg", "image": null, "enName": "Shaoxing wine"}, {"id": "i1", "name": "so", "qty": "400 g", "image": null, "enName": "Salt"}, {"id": "i2", "name": "tisztitott fokhagyma", "qty": "400 g", "image": null, "enName": "Garlic, peeled"}, {"id": "i3", "name": "cukor", "qty": "300 g", "image": null, "enName": "Sugar"}, {"id": "i4", "name": "msg", "qty": "200 g", "image": null, "enName": "MSG"}, {"id": "i5", "name": "feherbors", "qty": "50 g", "image": null, "enName": "White pepper"}, {"id": "i6", "name": "szezámolaj", "qty": "250 g", "image": null, "enName": "Sesame oil"}, {"id": "i7", "name": "csirke mell szeletek", "qty": "3 kg", "image": null, "enName": "Chicken breast slices"}, {"id": "i8", "name": "marinad", "qty": "0.5 kg", "image": null, "enName": "Marinade"}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
