INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-3-5', 'MARHA FAGGYU', 'Beef Tallow', 0, 3, 10, 20, 60, 'Head Chef', '[]'::jsonb, '[{"id": "s0", "desc": "vakum ellenőrzés. Amennyiben hibás, akkor új zsák.P0 Racionálba perforált GN-be teszem. 100 gőz 100 fok 60 perc.", "image": null, "enDesc": "Check vacuum seal. If defective, repackage. Place in perforated GN tray in the combi-oven. 100% steam at 100°C for 60 minutes."}, {"id": "s1", "desc": "Ezt követően átszüröm. 1 kg-os csomagokat készítek.", "image": null, "enDesc": "Strain afterwards. Portion into 1 kg packs."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-3-6', 'Marhahús leves porciók', 'Beef Broth Portions', 0, 3, 10, 20, 60, 'Head Chef', '[]'::jsonb, '[{"id": "s0", "desc": "Csontos marha oldalas. Vákum ellenőrzés vagy újra csomagolom. P3 programon vákumozom.", "image": null, "enDesc": "Bone-in beef short rib. Check vacuum or re-pack. Vacuum on P3 setting."}, {"id": "s1", "desc": "Berakom a gőzölőbe 80 fokra gőz programon a racionálba. Kínai gőzölő 80 fokos gőz. 8 óra a minimum vagy egy éjszaka.", "image": null, "enDesc": "Place in steamer at 80°C steam programme in the combi-oven. Chinese steamer at 80°C steam. 8 hours minimum or overnight."}, {"id": "s2", "desc": "Kész van a gőzben, akkor leszűröm, összegyűjtöm a folyadékot. Melegen csontozom.majd hűtöm, hogy tudjam szeletelni.Vékony szeletekre vágom.", "image": null, "enDesc": "When done in the steamer, strain and collect the liquid. De-bone while warm, then chill so it can be sliced. Slice thinly."}, {"id": "s3", "desc": "75 grammos csomagokat készítek sütőpapírba. A sütőpapírt negyedelem. 1 közepes zsákba 16 csomagot teszek.", "image": null, "enDesc": "Portion into 75 g packs in baking paper. Quarter the baking paper. Place 16 packs into one medium bag."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-3-7', 'CSIRKE bőr - sült', 'Crispy Chicken Skin', 0, 3, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Csirkebőr", "qty": "60 Kg", "image": null, "enName": "Chicken skin"}]'::jsonb, '[{"id": "s0", "desc": "NYers csirkebőrből probálok 50 kg os csomagokat csinálni.", "image": null, "enDesc": "Try to make 50 kg batches from raw chicken skin."}, {"id": "s1", "desc": "A csirke bőrt vákkumozd le. Vákum ellenőrzés. Tedd gőzölni 85C-ra 8.5 órára perforált gn edénybe.", "image": null, "enDesc": "Vacuum-pack the chicken skin. Check the seal. Steam at 85°C for 8.5 hours in a perforated GN tray."}, {"id": "s2", "desc": "Másnap nyisd ki a vákuum zsákot es szűrd egy 1/1-es mely tálcába amiben van egy 1/1-es perforalt tálca. Hagyd alaposan lecsöpögni és felgyűlt folyadékot helyezd a sokkolóba 3C fokra. 2 A már főtt csirkebőrt helyezd egy sima 1/1-es 65mm-es tepsibe es süsd a sütőben 170C-on, 0 páratartalommal 60 percig. Ezt követően 160 fokon 10 percenként alaposan keverd át egy fém kanállal es igyekezz fel kapirgálni a letapadt részeket. Csirke zsír szüz A GN edényben lehütöm. Elválik a zsír a kollagéntől. Folytatás a csirkebőr receptenk: Nem buborékozik a sült csirke zsír és kemény a bőr akkor van kész. Ezt követően leszűröm a sült zsirkeszírt és hűtöm, csomagolom. Csomagolom a sült csirkebőrt.", "image": null, "enDesc": "Next day, open the vacuum bag and strain into a deep 1/1 tray with a perforated 1/1 tray inside. Leave to drain thoroughly."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
