INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-3-11', 'Tonkatsu tarja', 'Tonkatsu Pork Collar', 0, 3, 10, 20, 60, 'Head Chef', '[]'::jsonb, '[{"id": "s0", "desc": "Vákum ellenőrzés. Amennyiben baj van , akkor újra vákumozás, vagy friss jön. Darabonként vákumozom.", "image": null, "enDesc": "Check vacuum seal. If faulty, re-vacuum or use a fresh piece. Vacuum-pack individually."}, {"id": "s1", "desc": "85 fokon gőzölöm egy éjszakát. Amint kész leszüröm. A lé az kuka.", "image": null, "enDesc": "Steam at 85°C overnight. Once done, strain. Discard the liquid."}, {"id": "s2", "desc": "A tarját kihűtöm sokkolóban vagy hűtőben. 150 grammonként szeletelem, fagyasztom majd csomagolom. 1 nagy zacsiba 15 szelet megy be.", "image": null, "enDesc": "Blast-chill or refrigerate. Slice into 150 g portions, freeze then pack. Place 15 slices in one large bag."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-3-12', 'SHA CHA CSIRKELÁB', 'Sha Cha Chicken Feet', 0, 3, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Csirkeláb", "qty": "10 kg", "image": null, "enName": "Chicken feet"}, {"id": "i1", "name": "Shaoxin főzőbor", "qty": "3000 g", "image": null, "enName": "Shaoxing cooking wine"}, {"id": "i2", "name": "Víz", "qty": "30 l", "image": null, "enName": "Water"}, {"id": "i3", "name": "Só", "qty": "100 g", "image": null, "enName": "Salt"}, {"id": "i4", "name": "cukor", "qty": "100 g", "image": null, "enName": "Sugar"}, {"id": "i5", "name": "Csillagánizs", "qty": "10 db", "image": null, "enName": "Star anise"}, {"id": "i6", "name": "Fahéj", "qty": "10 db", "image": null, "enName": "Cinnamon"}, {"id": "i7", "name": "darabolva", "qty": "1000 g", "image": null, "enName": "Chopped"}, {"id": "i8", "name": "felezve", "qty": "1000 g", "image": null, "enName": "Halved"}, {"id": "i9", "name": "Újhagyma főzőborral. Kb 30-40 perc alatt puhulásig kell főzni.", "qty": "1000 g", "image": null, "enName": "Spring onion. Cook in the cooking wine for approx. 30–40 minutes until tender."}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-3-13', 'SHAOXING CSIRKEROLÁD', 'Shaoxing Chicken Roll', 0, 3, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "kg     Bőrős csirkecomb filé", "qty": "10 kg", "image": null, "enName": "Skin-on chicken thigh fillet (per kg)"}, {"id": "i1", "name": "Shaoxin főzőbor", "qty": "2400 g", "image": null, "enName": "Shaoxing cooking wine"}, {"id": "i2", "name": "Víz", "qty": "3600 g", "image": null, "enName": "Water"}, {"id": "i3", "name": "Só", "qty": "70 g", "image": null, "enName": "Salt"}, {"id": "i4", "name": "cukor", "qty": "200 g", "image": null, "enName": "Sugar"}, {"id": "i5", "name": "Csillagánizs", "qty": "12 db", "image": null, "enName": "Star anise"}, {"id": "i6", "name": "Jujube", "qty": "240 g", "image": null, "enName": "Jujube (red dates)"}, {"id": "i7", "name": "Gyömbér", "qty": "250 g", "image": null, "enName": "Ginger"}, {"id": "i8", "name": "Goji", "qty": "120 g", "image": null, "enName": "Goji berries"}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-4-1', 'BROWNIE MOONCAKE', 'Brownie Mooncake', 4, 4, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "75%-os csoki", "qty": "1500 g", "image": null, "enName": "75% dark chocolate"}, {"id": "i1", "name": "vaj", "qty": "1150 g", "image": null, "enName": "Butter"}, {"id": "i2", "name": "cukor", "qty": "1700 g", "image": null, "enName": "Sugar"}, {"id": "i3", "name": "tojas", "qty": "20 db", "image": null, "enName": "Eggs"}, {"id": "i4", "name": "kakaopor", "qty": "300 g", "image": null, "enName": "Cocoa powder"}, {"id": "i5", "name": "aszalt szilva", "qty": "600 g", "image": null, "enName": "Prunes"}, {"id": "i6", "name": "simaliszt bl 55 finomliszt", "qty": "550 g", "image": null, "enName": "Plain flour (BL55)"}]'::jsonb, '[{"id": "s0", "desc": "1 A csokit és a vajat olvaszd össze gőz fölött. 2 A cukrot és a tojást verd fel a keverőgépben a habverő fejjel.", "image": null, "enDesc": "Melt the chocolate and butter together over a bain-marie. Beat the sugar and eggs in a mixer with the whisk attachment."}, {"id": "s1", "desc": "3 Az aszalt szilvát húsdarálon áttolom. Nem áztatom. 4 Az olvadt csokis vajas mixet adagold a tojásos cukros mixhez.", "image": null, "enDesc": "Pass the prunes through a meat grinder. Do not soak. Gradually fold the melted chocolate-butter mixture into the egg-sugar mixture."}, {"id": "s2", "desc": "5 Add hozzá a kakaoport es a lisztet es keverd el gépben. 6 Egy sutopapirral belelt 1/1-es tepsibe egyengesd el, rakj egy sutopapirt a tetejere es susd 130c-on 40 percig, a parat vedd le 50%-ra.", "image": null, "enDesc": "Add the cocoa powder and flour and mix in the machine. Spread evenly into a 1/1 baking tray lined with parchment. Place a weight on top and bake."}, {"id": "s3", "desc": "7 Hutsd be a sokkoloban 30 percre vagy hagyd a hűtóben másnapig. 8 Törd össze a gépben majd formázd 50 grammos golyókkal. —------------------------------------- ÖSSZEÁLLÍTÁS suly              alapanyag 50    g      brownie mix 5   g      sózott tojás mix 1 A brownie-t és a tölteléket is porciózd ki.", "image": null, "enDesc": "Cool in the blast chiller for 30 minutes or leave in the refrigerator overnight. Break apart in the machine then form into 50 g balls."}, {"id": "s4", "desc": "2 A brownie mixet kesztyűs kézzel lapítsd el és töltsd a közepébe a tojás mixet. 3 Óvatosan dolgozd el, úgy hogy a töltelék tökéletesen középen legyen.", "image": null, "enDesc": "Using gloved hands, flatten the brownie mix and fill the centre with the egg mixture. Gently work until the filling is fully enclosed."}, {"id": "s5", "desc": "4 Rakd a mooncake formába és tömörítsd be, ha a mooncake kis résein átjön a töltelék akkor túlnyomtad.", "image": null, "enDesc": "Place in the mooncake mould and press firmly. If filling comes out through the small holes, you have pressed too hard."}, {"id": "s6", "desc": "Igyekezz egy sütőpapírral leterített lapos felületen kinyomni. 5 Óvatosan emeld ki a formából sokkold le majd csomagold és hűtve tárold 2 hétig légmentesen záródó dobozban.", "image": null, "enDesc": "Try to press out on a flat surface lined with parchment. Carefully unmould, blast-chill then pack."}, {"id": "s7", "desc": "1 doboz 45 darab.", "image": null, "enDesc": "1 box = 45 pieces."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-4-2', 'SOZOTT TOJAS TOLTELEK', 'Salted Egg Filling', 4, 4, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "tojássárgája - pasztörizált", "qty": "400 g", "image": null, "enName": "Egg yolk, pasteurised"}, {"id": "i1", "name": "sózott kacsa tojás sárgája", "qty": "2 db", "image": null, "enName": "Salted duck egg yolk"}, {"id": "i2", "name": "só", "qty": "20 g", "image": null, "enName": "Salt"}, {"id": "i3", "name": "sárga folyékony ételfesték.", "qty": "2 g", "image": null, "enName": "Yellow liquid food colouring"}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-4-3', 'MÁLNÁS MOONCAKE', 'Raspberry Mooncake', 4, 4, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "fehércsoki", "qty": "600 g", "image": null, "enName": "White chocolate"}, {"id": "i1", "name": "vaj", "qty": "500 g", "image": null, "enName": "Butter"}, {"id": "i2", "name": "cukor", "qty": "850 g", "image": null, "enName": "Sugar"}, {"id": "i3", "name": "tojas", "qty": "12 db", "image": null, "enName": "Eggs"}, {"id": "i4", "name": "tejpor málnapor -lioflizált", "qty": "50 g", "image": null, "enName": "Milk powder and raspberry powder (freeze-dried)"}, {"id": "i5", "name": "málnából", "qty": "120 g", "image": null, "enName": "From raspberries"}, {"id": "i6", "name": "mandula liszt", "qty": "150 g", "image": null, "enName": "Almond flour"}, {"id": "i7", "name": "darált banán", "qty": "200 g", "image": null, "enName": "Mashed banana"}, {"id": "i8", "name": "simaliszt bl 55 finomliszt", "qty": "450 g", "image": null, "enName": "Plain flour (BL55)"}, {"id": "i9", "name": "malnapiros festek", "qty": "20 g", "image": null, "enName": "Raspberry red food colouring"}]'::jsonb, '[{"id": "s0", "desc": "Hozzáadási sorrend a dagasztóba: 1.tojásos cukor, 2. száraz anyagok, 3. vajas csoki keverés. 4. banán 5. ételfesték.", "image": null, "enDesc": "Order of addition to the mixer: 1. egg-sugar, 2. dry ingredients, 3. chocolate-butter mixture, 4. banana, 5. food colouring."}, {"id": "s1", "desc": "1 A málnaporhoz a liofilizált málnát a vitamixben porítsd le teljesen, majd szitáld át hogy ne maradjon benne mag.", "image": null, "enDesc": "For the raspberry powder, grind the freeze-dried raspberries completely in a Vitamix, then sieve to remove seeds."}, {"id": "s2", "desc": "Ezt a már kész átszitált port mérd a recepthez. 150g porhoz nagyjából 200g liofilizált málnára van szükséged.", "image": null, "enDesc": "Weigh the already-sieved powder for the recipe. You need approximately 200 g freeze-dried raspberries per 150 g powder."}, {"id": "s3", "desc": "1 A fehércsokit és a vajat olvaszd össze gőz fölött. 2 A cukrot és a tojást verd fel a keverőgépben a habverő fejjel, ellenőrizd, hogy a cukor feloldódjon, ha szükséges akkor porítsd a thermoban a cukrot mielőtt felhasználod.", "image": null, "enDesc": "Melt the white chocolate and butter together over a bain-marie. Beat the sugar and eggs in a mixer with the whisk attachment until light."}, {"id": "s4", "desc": "Add hozzá a banán pürét. 3 Az olvadt csokis vajas mixet adagold a tojásos cukros mixhez és alaposan keverd el.", "image": null, "enDesc": "Add the banana purée. Gradually fold the melted chocolate-butter mixture into the egg-sugar mixture and mix thoroughly."}, {"id": "s5", "desc": "4 Add hozzá a tejport, málna port és a lisztet majd keverd el. 5 Egy sütőpapírral bélelt 1/1-es tepsibe egyengesd el, rakj egy sütőpapírt a tetejére és süsd 130c-on 50 percig.", "image": null, "enDesc": "Add the milk powder, raspberry powder, and flour, then mix. Spread into a 1/1 baking tray lined with parchment."}, {"id": "s6", "desc": "40% gőz. Csak sütés! 8 Hűtsd le a sokkolóban 30 percre.", "image": null, "enDesc": "40% steam. Bake only! Cool in the blast chiller for 30 minutes."}, {"id": "s7", "desc": "8 Vedd ki és kesztyűs kézzel alaposan gyúrd át amíg egy homogén tésztát nem kapsz. 9 Dobozold be.", "image": null, "enDesc": "Remove and knead thoroughly with gloved hands until a homogenous dough forms. Box up."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-4-4', 'Tangzhong', 'Tangzhong (Water Roux)', 4, 4, 10, 20, 60, 'Head Chef', '[]'::jsonb, '[{"id": "s0", "desc": "Merd ki a lisztet es kulon a vizet. A liszthez adagolva a vizet eloszor keverd nagyon surure hogy ne maradjon benne csomo majd higitsd aprankent a maradek vizzel.", "image": null, "enDesc": "Weigh the flour separately and the water separately. Add water to the flour gradually, stirring vigorously first to avoid lumps."}, {"id": "s1", "desc": "A nagy gyorsforraloban 3-as fokozaton az indukcon melegitsd fel 65c-ra mindig csekkold a homersekletet a meghomerovel.", "image": null, "enDesc": "Heat in the rapid boiler on setting 3 on the induction, heating to 65°C. Always check the temperature with a probe thermometer."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-4-5', 'Bao', 'Bao Bun', 4, 4, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Rétesliszt", "qty": "2.5 kg", "image": null, "enName": "Bread flour"}, {"id": "i1", "name": "Tejpor", "qty": "333 g", "image": null, "enName": "Milk powder"}, {"id": "i2", "name": "Só", "qty": "20 g", "image": null, "enName": "Salt"}, {"id": "i3", "name": "Kínai sütőpor", "qty": "20 g", "image": null, "enName": "Chinese baking powder"}, {"id": "i4", "name": "glutén v. búzasikér", "qty": "25 g", "image": null, "enName": "Gluten / wheat gluten"}, {"id": "i5", "name": "Cukor", "qty": "240 g", "image": null, "enName": "Sugar"}, {"id": "i6", "name": "Friss élesztő - budafoki", "qty": "25 g", "image": null, "enName": "Fresh yeast (Budafoki)"}, {"id": "i7", "name": "Viz", "qty": "420 g", "image": null, "enName": "Water"}, {"id": "i8", "name": "Olaj- repce", "qty": "130 g", "image": null, "enName": "Rapeseed oil"}, {"id": "i9", "name": "Tangzhong", "qty": "1000 g", "image": null, "enName": "Tangzhong"}]'::jsonb, '[{"id": "s0", "desc": "Meleg vízben(max 40 fok) oldd fel a cukrot, majd morzsold bele az élesztőt, és keverd el alaposan. 15 percet áll.", "image": null, "enDesc": "Dissolve the sugar in warm water (max 40°C), then crumble in the yeast and stir thoroughly. Leave to stand for 15 minutes."}, {"id": "s1", "desc": "Ameddig áll addig mérd ki a szárazárut(liszt, só, kínai sütópor, buzasiker) és tedd bele a dagasztóba. Ezt be kell kapcsolni. Gyors fokozaton.", "image": null, "enDesc": "While it stands, weigh out the dry ingredients (flour, salt, Chinese baking powder, wheat gluten) and place in the mixer. Start the machine."}, {"id": "s2", "desc": "Ameddig kavarog, addig mérd rá az olajat a cukros élesztős vízre.", "image": null, "enDesc": "While the machine is running, pour the oil into the sugar-yeast water."}, {"id": "s3", "desc": "Mérd ki a tangzhong külön edénybe.", "image": null, "enDesc": "Weigh out the tangzhong into a separate container."}, {"id": "s4", "desc": "A gépbe add hozzá a folyadékokat. Előszor a cukros élesztős vizet, majd a tangzhong -ot.", "image": null, "enDesc": "Add the liquids to the machine. First the sugar-yeast water, then the tangzhong."}, {"id": "s5", "desc": "Hagyd menni a gépet 15 percig. Tésztagyúrás.", "image": null, "enDesc": "Run the machine for 15 minutes. Knead the dough."}, {"id": "s6", "desc": "Kiveszed a tésztát és átgyúrod.Ezt követően szétszeded 2250 g- os labdákra.", "image": null, "enDesc": "Remove the dough and knead by hand. Then divide into 2,250 g balls."}, {"id": "s7", "desc": "A labdákat a beolajozott lapon pizza alakőra nyújtod a formázó lapon.", "image": null, "enDesc": "Roll each ball into a pizza shape on an oiled surface."}, {"id": "s8", "desc": "Zsemle kerekítő gépbe beteszed. Rutinszerűen vágod. 10. 74,5 g - 75,5 g golyókat csinálsz. Mérleggel méred ki.", "image": null, "enDesc": "Feed into the bun-rounding machine. Cut routinely. Weigh into 74.5–75.5 g balls on the scale."}, {"id": "s9", "desc": "Kézzel bao kerekítés. Mantao: kész Shiao song : hosszú hengerekete gyúrsz Gua : Kézzel kilapított kerek alakúra, majd nyújtógéppel kinyújtod. Olajozod és félbe hajtod. 12. 70 percig keleszted. !! Amennyiben nem kel meg, akkor még hagyod állni.", "image": null, "enDesc": "Hand-round bao shape. Mantao: done. Shiao song: roll into long cylinders. Gua: hand-flatten into a round, then fold."}, {"id": "s10", "desc": "KÍnai gőzölőben 100 fok 6 perc, 110 fokon 6 perc", "image": null, "enDesc": "Steam in Chinese steamer at 100°C for 6 minutes, then at 110°C for 6 minutes."}, {"id": "s11", "desc": "Kihűtöd és csomagolod. Nagy zacsiba Gua: 16 - Shia song: 18 - Mantao: 20", "image": null, "enDesc": "Cool and pack. Per large bag — Gua: 16, Shiao song: 18, Mantao: 20."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-4-6', 'Bao morzsa', 'Bao Breadcrumbs', 4, 4, 10, 20, 60, 'Head Chef', '[]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-4-7', 'SHOKUPAN (KENYÉR)', 'Shokupan (Japanese Milk Bread)', 4, 4, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Rétesliszt", "qty": "2.5 kg", "image": null, "enName": "Bread flour"}, {"id": "i1", "name": "Tejpor", "qty": "333 g", "image": null, "enName": "Milk powder"}, {"id": "i2", "name": "Só", "qty": "20 g", "image": null, "enName": "Salt"}, {"id": "i3", "name": "glutén", "qty": "5 g", "image": null, "enName": "Gluten"}, {"id": "i4", "name": "Cukor", "qty": "240 g", "image": null, "enName": "Sugar"}, {"id": "i5", "name": "Friss élesztő", "qty": "25 g", "image": null, "enName": "Fresh yeast"}, {"id": "i6", "name": "Viz (hideg)", "qty": "800 g", "image": null, "enName": "Water (cold)"}, {"id": "i7", "name": "Olaj", "qty": "185 g", "image": null, "enName": "Oil"}, {"id": "i8", "name": "Tangzhong (hideg) alaposan. 15 percet áll. dagasztóba. Ezt be kell kapcsolni. Gyors fokozaton. hosszabbik oldalan a szeleket majd teker fel a rovidebb oldalról mint egy palacsintát, hogy egy vastag de keskeny csigát kapj ami kozepen kisse keskenyebb. hogy a hosszabbik oldalon átlógjon a sütőpapír. csigák spirál nézeti felülete a GN edény hosszabbik oldala felé nézzen (mint a képen) folyamatosan ellenőrizd, neha sokkal elobb megkel, van amikor tobb idore van szuksege) egy kisebb idore rakd a hutobe, hogy konnyebb legyen szeletelni, sutes utan 2 oraig ne szeleteld mert osszeugrik a belseje es szalonnas lesz.", "qty": "1200 g", "image": null, "enName": "Tangzhong (cold) — mix thoroughly. Rest 15 minutes. Into the mixer. Switch on the machine. High speed. Fold the edges of the longer side and roll up from the shorter side like a crêpe to form a thick but narrow scroll that is slightly narrower in the centre. The longer side of the scroll should overhang the baking paper. The spiral face of the scrolls should face the longer side of the GN tray. Monitor constantly — sometimes it rises much sooner; sometimes it needs more time. Place in the fridge for a while to make it easier to slice. Do not slice within 2 hours of baking or the inside will collapse and become greasy."}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-5-1', 'dumpling tészta', 'Dumpling Dough', 3, 5, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "víz", "qty": "500 g", "image": null, "enName": "Water"}, {"id": "i1", "name": "só", "qty": "5 g", "image": null, "enName": "Salt"}, {"id": "i2", "name": "víz", "qty": "500 g", "image": null, "enName": "Water"}, {"id": "i3", "name": "só", "qty": "5 g", "image": null, "enName": "Salt"}, {"id": "i4", "name": "folyékony ételfesték", "qty": "10 g", "image": null, "enName": "Liquid food colouring"}, {"id": "i5", "name": "víz 1g ételfestékpor.", "qty": "30 ml", "image": null, "enName": "Water + 1 g food colouring powder"}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-5-2', 'sertés', 'Pork Dumpling Filling', 3, 5, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "darált sertéshús .Tarját kell ledarálni.", "qty": "1000 g", "image": null, "enName": "Minced pork (collar, minced)"}, {"id": "i1", "name": "világos szójaszósz", "qty": "165 g", "image": null, "enName": "Light soy sauce"}, {"id": "i2", "name": "csirkepor Knorr maggi csirkeleves por", "qty": "20 g", "image": null, "enName": "Chicken powder (Knorr / Maggi chicken stock powder)"}, {"id": "i3", "name": "osztriga szósz", "qty": "80 g", "image": null, "enName": "Oyster sauce"}, {"id": "i4", "name": "finomra vágott gyömbér", "qty": "30 g", "image": null, "enName": "Ginger, finely chopped"}, {"id": "i5", "name": "szezám olaj", "qty": "90 g", "image": null, "enName": "Sesame oil"}, {"id": "i6", "name": "egész tojás", "qty": "2 db", "image": null, "enName": "Whole egg"}, {"id": "i7", "name": "kínai metélőhagyma", "qty": "125 g", "image": null, "enName": "Chinese chives"}, {"id": "i8", "name": "garnéla 26/30-as", "qty": "250 g", "image": null, "enName": "Prawns (26/30)"}, {"id": "i9", "name": "víz", "qty": "280 g", "image": null, "enName": "Water"}, {"id": "i10", "name": "tojás rántottának", "qty": "4 db", "image": null, "enName": "Egg for scrambling"}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-5-3', 'csirkés', 'Chicken Dumpling Filling', 3, 5, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "csirkecomb filé bőr nélkül - darálva", "qty": "1000 g", "image": null, "enName": "Chicken thigh fillet, skinless, minced"}, {"id": "i1", "name": "shaoxing", "qty": "90 g", "image": null, "enName": "Shaoxing wine"}, {"id": "i2", "name": "vilagos szójaszósz", "qty": "85 g", "image": null, "enName": "Light soy sauce"}, {"id": "i3", "name": "szezám olaj", "qty": "12 g", "image": null, "enName": "Sesame oil"}, {"id": "i4", "name": "só", "qty": "7 g", "image": null, "enName": "Salt"}, {"id": "i5", "name": "cukor", "qty": "22 g", "image": null, "enName": "Sugar"}, {"id": "i6", "name": "örölt fehérbors", "qty": "3 g", "image": null, "enName": "Ground white pepper"}, {"id": "i7", "name": "kukorica", "qty": "900 g", "image": null, "enName": "Cornstarch"}, {"id": "i8", "name": "salotta", "qty": "100 g", "image": null, "enName": "Shallot"}, {"id": "i9", "name": "újhagyma", "qty": "200 g", "image": null, "enName": "Spring onion"}, {"id": "i10", "name": "vaj", "qty": "120 g", "image": null, "enName": "Butter"}, {"id": "i11", "name": "víz", "qty": "120 g", "image": null, "enName": "Water"}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
