INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-6-4', 'savanytott shitake gomba', 'Pickled Shiitake', 5, 6, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "rizs ecet", "qty": "1 kg", "image": null, "enName": "Rice vinegar"}, {"id": "i1", "name": "viz", "qty": "1 kg", "image": null, "enName": "Water"}, {"id": "i2", "name": "cukor", "qty": "500 g", "image": null, "enName": "Sugar"}, {"id": "i3", "name": "szaritott, fott shiitake", "qty": "1 kg", "image": null, "enName": "Dried, cooked shiitake"}, {"id": "i4", "name": "savanyitole", "qty": "1000 g", "image": null, "enName": "Pickling liquid"}]'::jsonb, '[{"id": "s0", "desc": "1 Keverj mindent ossze es vakuumozd le. 2 Ha nincs a gomba megfozve, akkor aztass be gombat 100szoro mennyisegu vizbe (50g gomba 5l viz) es fozd 90c-on 90 percet. Szurd le es a levet add oda a tigrisnek. Meg kell kérdezni. A gombának csak a feje kell.", "image": null, "enDesc": "Mix all together and vacuum-pack. If mushrooms are uncooked, soak in 100× their weight in water (50 g mushroom : 5 L water) before using."}, {"id": "s1", "desc": "Csomagolni 1 kg kell közepes zacsiba P2 vagy 3 programon.", "image": null, "enDesc": "Pack in 1 kg portions in medium bags on P2 or P3 programme."}, {"id": "s2", "desc": "Hűtöben tároljuk.", "image": null, "enDesc": "Store in the refrigerator."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-6-5', 'Koji rizs', 'Koji Rice', 5, 6, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "jazmin rizs", "qty": "6 kg", "image": null, "enName": "Jasmine rice"}, {"id": "i1", "name": "viz rola a vizet. Ezt ismeteld meg meg ketszer, majd ontsd fel annyi vizzel, hogy a viz legalabb hatni, de ez nem baj, mert ha tulfozod, akkor a koji spora nem tud megtelepedni.", "qty": "12 l", "image": null, "enName": "Water (rinse and repeat twice, then cover with water to at least 6 cm above; slight overcooking is fine as koji spores won''t colonise if overcooked)"}, {"id": "i2", "name": "gozolt rizs", "qty": "10 kg", "image": null, "enName": "Steamed rice"}, {"id": "i3", "name": "spora", "qty": "1.2 g", "image": null, "enName": "Koji spores"}, {"id": "i4", "name": "burgonya kemenyito talcaba merd oket kulon kulon, a lenyeg az, hogy kenyelmesen tudj dolgozni es at tudd alaposan keverni a rizst. darabokat, de a szemeket probald ne szettorni, maradjanak egyben. hogy ellepje a konyharuhakat, majd forrald fel, es fozd a konyharuhat 5-10 percig, hogy sterilizald azt is. Egy csipesszel szedd at egy frissen mosott talcara es hideg vizzel mosd at, mjad csavard ki oket. adagolva alaposan keverd el a rizzsel. Igyekezz tenyleg elkepesztoen alaposan atkeverni a kojit a rizzsel, kulonben nem fog noni rajta normalisan a koji. Ha nincs eleg hely a mely talcadban, akkor aranyosan oszd annyi fele a kojit olyan aranyban, mint ahogy a rizsed van. hogy a konyharuha enyhen tullogjon a talca feluleten. Aranyosan oszd el a kojit, egy talcaba megkozelitoleg 2-2.5kg rizs fer el, NE pupozd a kojit, ha szukseges akkor fogj be meg egy talcat, es meg tobb konyharuhat sterilizalj. ne szaradjon ki a rizsed. logjon ki a regal keretebol. regal fuggoleges rudjara, ugy, hogy befele nezzen a regal belseje fele. es takargasd vissza a konyharuhaval. kabele kinnt maradjon, es ugyelj, hogy az erzekelok ne mozduljanak el. gepet. kijelzojen. futes megy e rajta. ovatosan huzd ki a talcakat, vegyel fel egy kesztyut es ellenorizd a kojit, ha mindent jol csinaltal akkor a rizsszemeken, latnod kell feheres elszinezodeseket, amik a micelium megjelenesere utalnak. egyenkent nagyon alaposam, itt ott a miceliumtol ossze lesz mar tapadva, az a celod, hogy ezeket minel alaposan el tudd oszlatni. tudja a legtobb hot leadni a koji, ha ezt nem teszed meg akkor a koji, az eletciklusaban tul sok hot fog termelni, aminek hatasara sajat magat fojtja le, es meg ido elott megdoglik, ezert ezt a lepest, ne sporold el. Ha biztosra akarsz menni, akkor 12 ora elteltevel keverd at megegyszer. helyezd vissza a kojis talcakat a regalra fuggolegesen nezve forditva, mint ahogy beraktad, azaz a felso kerul alulra es forditva, helyezd vissza a homerot a kozepso rizs kozepebe, es folpackkal alaposan tekerd megint korbe, ellenorizd a parasitot, es a radiator, es hagyd inkubalodni a kovetkezo 24 orara. fokot, ezert ha szukseges akkor szelloztesd, vagy morzsold el ujra. masnap, feltordeles nelkul, 50%-os vakuumon vakuumcsomagold 1kg-kent.", "qty": "20 g", "image": null, "enName": "Potato starch (weigh separately in trays; the key is to be comfortable and able to mix the rice thoroughly; try not to crush the grains. Sterilise cloths by boiling in water 5–10 min. Transfer to a freshly washed tray and rinse with cold water, wring out. Mix koji into the rice in small batches, mixing extremely thoroughly — poor mixing = poor koji growth. Divide evenly among trays (approx. 2–2.5 kg rice per tray). Do not heap. The cloth should slightly overhang the tray. Spread evenly. Monitor every 12 hours; stir again if needed. Rotate trays vertically after 24 hours. Keep probe in the centre. Check humidity and heating. Vacuum-pack 1 kg portions at 50% on 50% vacuum the next day."}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
