INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-7-1', 'DAIKON CAKE', 'Daikon Cake (Lo Bak Go)', 3, 7, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "karalábé v. jégcsapretek", "qty": "1800 g", "image": null, "enName": "Kohlrabi or icicle radish"}, {"id": "i1", "name": "Kukoricakeményítő", "qty": "800 g", "image": null, "enName": "Cornstarch"}, {"id": "i2", "name": "Szezám olaj", "qty": "40 g", "image": null, "enName": "Sesame oil"}, {"id": "i3", "name": "Ropogós hagyma", "qty": "400 g", "image": null, "enName": "Crispy fried onion"}, {"id": "i4", "name": "só", "qty": "16 g", "image": null, "enName": "Salt"}, {"id": "i5", "name": "cukor", "qty": "20 g", "image": null, "enName": "Sugar"}, {"id": "i6", "name": "őrölt feherbors", "qty": "2 g", "image": null, "enName": "Ground white pepper"}, {"id": "i7", "name": "Gomba por", "qty": "30 g", "image": null, "enName": "Mushroom powder"}, {"id": "i8", "name": "Ragacsos rizsliszt", "qty": "400 g", "image": null, "enName": "Glutinous rice flour"}, {"id": "i9", "name": "Víz", "qty": "1500 g", "image": null, "enName": "Water"}]'::jsonb, '[{"id": "s0", "desc": "Az 1800 g az a tisztított, sózott mennyiség. Megjön a jégcsapretek, amit megpucolok.Lereszelem a géppel. besózom, Hagyom állni 30 percet majd kinyomkodom. Le kell súlyozni, hogy kicsepegjen. Ezt követően lemérem és ehhez igazítom a receptet.", "image": null, "enDesc": "Starting weight is 1,800 g of cleaned, salted radish. Peel the incoming icicle radish. Grate with the machine, salt and leave to stand."}, {"id": "s1", "desc": "Kimérem a száraz cuccokat egy külön edényben.Kukoricakeményítő,Ropogós hagyma,só, cukor,őrölt feherbors, Gomba por", "image": null, "enDesc": "Weigh out the dry ingredients in a separate container: cornstarch, crispy onion, salt, sugar, ground white pepper, mushroom powder."}, {"id": "s2", "desc": "Egy edényben a ragacsos rizslisztet keverd össze a vízzel. Nagy hőmérséklettel kezdve, és folyamatosan csökkentve a hőmérsékletet főzd amíg az egész nem áll össze egy ragacsos tésztává. Ekkor kapcsold le.", "image": null, "enDesc": "In a container, mix the glutinous rice flour with the water. Starting at high heat and gradually reducing, cook until the mixture thickens into a paste."}, {"id": "s3", "desc": "A kicsavart reteket illetve a már összefőzött ragacsos rizsliszt tésztát keverd össze az összes többi alapanyaggal.", "image": null, "enDesc": "Mix the squeezed radish and the cooked glutinous rice paste together with all the remaining dry ingredients."}, {"id": "s4", "desc": "Bélelj ki sütőpapírral egy gn talcat. A mixet ontsd a tepsibe es fedd le megegy reteg sutopapirral. Gőzöld ki 100C fokon 1óráig majd a sokkolóban hűtsd le 3c fokra.", "image": null, "enDesc": "Line a GN tray with baking paper. Pour in the mix and cover with another layer of baking paper. Steam at 100°C for 45 minutes."}, {"id": "s5", "desc": "Porciózd 70g-os négyzet alakú szeletekre.", "image": null, "enDesc": "Portion into 70 g square slices."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-8-1', 'RAMEN TÉSZTA', 'Ramen Noodle Dough', 3, 8, 10, 20, 60, 'Head Chef', '[]'::jsonb, '[{"id": "s0", "desc": "Szódabikarbóna kisütjük a racionálban. 0% párával 120 fokon 1-1,5 órán keresztül.", "image": null, "enDesc": "Bake the bicarbonate of soda in the combi-oven. 0% humidity at 120°C for 1–1.5 hours."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
