INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-9-1', 'SZECSUÁNI CHILLI OLAJ', 'Sichuan Chilli Oil', 0, 9, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Repce olaj", "qty": "18000 g", "image": null, "enName": "Rapeseed oil"}, {"id": "i1", "name": "Fokhagyma", "qty": "1080 g", "image": null, "enName": "Garlic"}, {"id": "i2", "name": "Gyömbér", "qty": "1200 g", "image": null, "enName": "Ginger"}, {"id": "i3", "name": "Csillagánizs", "qty": "180 g", "image": null, "enName": "Star anise"}, {"id": "i4", "name": "Koriander mag", "qty": "110 g", "image": null, "enName": "Coriander seeds"}, {"id": "i5", "name": "Szecsuáni vörös bors", "qty": "900 g", "image": null, "enName": "Sichuan red peppercorns"}, {"id": "i6", "name": "Koreai chilli pehely (gochugaru)", "qty": "3600 g", "image": null, "enName": "Korean chilli flakes (gochugaru)"}, {"id": "i7", "name": "Só", "qty": "250 g", "image": null, "enName": "Salt"}, {"id": "i8", "name": "Szezám Olaj", "qty": "500 g", "image": null, "enName": "Sesame oil"}]'::jsonb, '[{"id": "s0", "desc": "A szecsuáni borsot, a koriandert es a csillagánizst mérd ki és 170C fokos sütőben 2-es légkeringetés mellett szárazon pirítsd meg lapos tálcákon úgy 8 percig. A fűszereket 500 g onként tedd egy tálcára.", "image": null, "enDesc": "Weigh the Sichuan pepper, coriander, and star anise, and dry-roast in the oven at 170°C with fan level 2."}, {"id": "s1", "desc": "Keverj össze minden szaraz fuszert beleértve a gochugarut is. őröld porrá az összeset és rakd egy 50 literes fazékba.", "image": null, "enDesc": "Mix all the dry spices together including the gochugaru. Grind everything to a powder and place in a 50-litre pot."}, {"id": "s2", "desc": "Melegítsd fel az olajat 150 fokra és ráöntöd a száraz füszerekre.", "image": null, "enDesc": "Heat the oil to 150°C and pour over the dry spices."}, {"id": "s3", "desc": "Alaposan keverd el az olajat a fűszerekkel és hagyd állni 1 napot majd szűrd le az olajat párnahuzattal. A chilli morzsát vedd külön és vákuumozd le. 1 kg onként. Az olaj innen már használhato 3 hónap az eltarthatósági ideje.", "image": null, "enDesc": "Mix the oil thoroughly with the spices and leave to stand for 1 day, then strain the oil through a pillowcase. The chilli crumble is what remains."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
