INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-9-4', '101 SZECSUÁNI CHILLI Morzsa', '101 Sichuan Chilli Crumble', 0, 9, 10, 20, 60, 'Head Chef', '[]'::jsonb, '[{"id": "s0", "desc": "A sült hagymát a robo coop kutterben őröld kisebb darabokra.", "image": null, "enDesc": "Grind the fried onion into smaller pieces in the Robot Coupe cutter."}, {"id": "s1", "desc": "A fermentált feketebabot szintén vágd a robo coop kutterben kisebb darabokra.", "image": null, "enDesc": "Also cut the fermented black beans into smaller pieces in the Robot Coupe cutter."}, {"id": "s2", "desc": "Az összes hozzávalót alaposan keverd el.", "image": null, "enDesc": "Mix all ingredients thoroughly."}, {"id": "s3", "desc": "Kis üveg edényekbe mérd ki. Először az olajat tedd bele. 30 g szecsuáni chili olajat raksz majd 100 g morzsát.", "image": null, "enDesc": "Portion into small glass jars. Add the oil first — 30 g Sichuan chilli oil — then top with 100 g crumble."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-9-5', 'chonquing fűszer', 'Chongqing Spice Blend', 0, 9, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "zöld szecsuani bors", "qty": "1000 g", "image": null, "enName": "Green Sichuan pepper"}, {"id": "i1", "name": "édes kömenymag", "qty": "250 g", "image": null, "enName": "Sweet fennel seeds"}, {"id": "i2", "name": "romai kömeny", "qty": "150 g", "image": null, "enName": "Cumin seeds"}, {"id": "i3", "name": "szegfűszeg", "qty": "100 g", "image": null, "enName": "Cloves"}, {"id": "i4", "name": "fekete kardamon", "qty": "10 db", "image": null, "enName": "Black cardamom"}, {"id": "i5", "name": "csillaganizs", "qty": "5 db", "image": null, "enName": "Star anise"}, {"id": "i6", "name": "fehér bors egész", "qty": "100 g", "image": null, "enName": "Whole white pepper"}, {"id": "i7", "name": "koreai chili pehely gochugaru", "qty": "1000 g", "image": null, "enName": "Korean chilli flakes (gochugaru)"}, {"id": "i8", "name": "cukor", "qty": "1000 g", "image": null, "enName": "Sugar"}, {"id": "i9", "name": "msg", "qty": "200 g", "image": null, "enName": "MSG"}, {"id": "i10", "name": "dinatrium", "qty": "20 g", "image": null, "enName": "Disodium"}, {"id": "i11", "name": "só", "qty": "1500 g", "image": null, "enName": "Salt"}]'::jsonb, '[{"id": "s0", "desc": "1.zöld szecsuani bors,édes köménymag, római kömény, szegfűszeg, fekete kardamon, fehér bors, csillagánizs gn tálcára teszem és 150 fokon 0 pára mellett 1 es légkeverésen megpiritom.", "image": null, "enDesc": "Place the green Sichuan pepper, sweet fennel, cumin, cloves, black cardamom, white pepper, and star anise on a GN tray."}, {"id": "s1", "desc": "2.gochugaru, cukor, msg, só, dinatrium hozáádaom és leporítom vitamixerben. 3. szitáld le a mixet és tárolom egy dobozban a tigrisben, a többit vákumozom 500 grammonként.", "image": null, "enDesc": "Add gochugaru, sugar, MSG, salt, and disodium. Grind everything to a powder in a Vitamix. Sieve the mix and store in a container."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-9-6', '101 chonquing fűszer', '101 Chongqing Spice Blend', 0, 9, 10, 20, 60, 'Head Chef', '[]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-9-7', 'Popcorn spice', 'Popcorn Spice', 0, 9, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Zold szecsuani bors", "qty": "150 g", "image": null, "enName": "Green Sichuan pepper"}, {"id": "i1", "name": "Edeskomeny mag", "qty": "150 g", "image": null, "enName": "Sweet fennel seeds"}, {"id": "i2", "name": "5 fuszer", "qty": "300 g", "image": null, "enName": "Five-spice powder"}, {"id": "i3", "name": "So", "qty": "2200 g", "image": null, "enName": "Salt"}, {"id": "i4", "name": "Cukor", "qty": "2200 g", "image": null, "enName": "Sugar"}, {"id": "i5", "name": "Msg felezve:", "qty": "1100 g", "image": null, "enName": "MSG (halved quantity)"}, {"id": "i6", "name": "Zold szecsuani bors", "qty": "75 g", "image": null, "enName": "Green Sichuan pepper"}, {"id": "i7", "name": "Edeskomeny mag", "qty": "75 g", "image": null, "enName": "Sweet fennel seeds"}, {"id": "i8", "name": "5 fuszer", "qty": "150 g", "image": null, "enName": "Five-spice powder"}, {"id": "i9", "name": "So", "qty": "1100 g", "image": null, "enName": "Salt"}, {"id": "i10", "name": "Cukor", "qty": "1100 g", "image": null, "enName": "Sugar"}, {"id": "i11", "name": "Msg", "qty": "550 g", "image": null, "enName": "MSG"}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-9-8', 'SZECSUÁNI SÓ', 'Sichuan Salt', 0, 9, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "pirított zöld szecsuáni bors", "qty": "500 g", "image": null, "enName": "Toasted green Sichuan pepper"}, {"id": "i1", "name": "pirított édeskömény", "qty": "250 g", "image": null, "enName": "Toasted sweet fennel"}, {"id": "i2", "name": "só", "qty": "750 g", "image": null, "enName": "Salt"}, {"id": "i3", "name": "cukor", "qty": "250 g", "image": null, "enName": "Sugar"}, {"id": "i4", "name": "msg", "qty": "150 g", "image": null, "enName": "MSG"}, {"id": "i5", "name": "dinátrium 5’ ribonukleotid percig. Hagyd lehulni es a vitamixbe poritsd. egy talcaba es a sot a vegen add hozza es kezzel keverd el.", "qty": "15 g", "image": null, "enName": "Disodium 5-ribonucleotide (toast for several minutes, leave to cool, grind in a Vitamix, sieve into a tray, add salt at the end and mix by hand)"}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-9-9', 'MALNA SÓ', 'Raspberry Salt', 0, 9, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "porított átszitált liofilizált málna por", "qty": "500 g", "image": null, "enName": "Powdered, sieved freeze-dried raspberry powder"}, {"id": "i1", "name": "só", "qty": "500 g", "image": null, "enName": "Salt"}, {"id": "i2", "name": "cukor", "qty": "500 g", "image": null, "enName": "Sugar"}, {"id": "i3", "name": "msg", "qty": "250 g", "image": null, "enName": "MSG"}, {"id": "i4", "name": "dinátrium 5’ ribonukleotid", "qty": "10 g", "image": null, "enName": "Disodium 5-ribonucleotide"}, {"id": "i5", "name": "citromsav", "qty": "10 g", "image": null, "enName": "Citric acid"}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-9-10', 'cukros mogyoró', 'Candied Peanuts', 0, 9, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "Sótlan mogyoró", "qty": "1 kg", "image": null, "enName": "Unsalted peanuts"}, {"id": "i1", "name": "kristálycukor", "qty": "200 g", "image": null, "enName": "Caster sugar"}]'::jsonb, '[{"id": "s0", "desc": "A mogyorót rakd egy fazékbe és öntsd fel annyi vízzel, hogy 5cm-re ellepje a víz. Forrald fel a legnagyobb fokozaton. Amint felforrt kizárom és leöntöm. Összesen 3x csinéld meg.", "image": null, "enDesc": "Place the peanuts in a pot and cover with water by 5 cm. Bring to a boil on the highest setting. Once boiling, drain, rinse and repeat."}, {"id": "s1", "desc": "Utolsó forrázás után szűrd le, csöpögtesd le a vizet róla és rakd a perforált 1/1-es tálcába.", "image": null, "enDesc": "After the final blanching, drain, allow to drip dry and place in a perforated 1/1 tray."}, {"id": "s2", "desc": "A rationált állítsd be 140C-ra 0% páratatalomra. Süsd 30percig, majd vedd le a hőfokot és süsd további 2 orat 120C-on 0% páratartalom mellett.", "image": null, "enDesc": "Set the combi-oven to 140°C, 0% humidity. Bake for 30 minutes, then reduce temperature and bake a further 2 hours at 120°C, 0%."}, {"id": "s3", "desc": "Várd meg amíg szobahőmérsékletre hűlt.", "image": null, "enDesc": "Wait until cooled to room temperature."}, {"id": "s4", "desc": "Itt adom hozzá a cukrot. A robocook kutterben a forrázott szaritott mogyorót kisebb adagokban a legalacsonyabb fordulatszámon daráld le a cukorral, de ügyelj rá hogy nehogy túldolgozd különben összeáll az egész.", "image": null, "enDesc": "Add the sugar. In a Robot Coupe cutter, process the blanched dried peanuts in small batches on the lowest speed setting."}, {"id": "s5", "desc": "Vakuumzacsiban 6 hónapig eláll.", "image": null, "enDesc": "Vacuum-packed, keeps for 6 months."}]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO recipes (id, hu_name, en_name, category, section, serves, prep_time, cook_time, author_name, ingredients, steps, is_seed) VALUES ('pdf-10-1', 'lakkozott', 'Lacquered Nuts', 0, 10, 10, 20, 60, 'Head Chef', '[{"id": "i0", "name": "kesudió", "qty": "2 kg", "image": null, "enName": "Cashew nuts"}, {"id": "i1", "name": "japan szója", "qty": "200 g", "image": null, "enName": "Japanese soy sauce"}, {"id": "i2", "name": "maggi speciális, nem sárga flakonos", "qty": "50 g", "image": null, "enName": "Maggi special (not yellow bottle)"}, {"id": "i3", "name": "tengeri só éjszakára. lakkozott Mandula", "qty": "20 g", "image": null, "enName": "Sea salt — soak overnight. Lacquered almond."}, {"id": "i4", "name": "blansírozott mandula", "qty": "2 kg", "image": null, "enName": "Blanched almonds"}, {"id": "i5", "name": "japan szója", "qty": "200 g", "image": null, "enName": "Japanese soy sauce"}, {"id": "i6", "name": "maggi speciális, nem sárga flakonos", "qty": "50 g", "image": null, "enName": "Maggi special (not yellow bottle)"}, {"id": "i7", "name": "tengeri só lakkozott mogyoró", "qty": "20 g", "image": null, "enName": "Sea salt — lacquered peanut."}, {"id": "i8", "name": "sózatlan földi mogyoró", "qty": "2 kg", "image": null, "enName": "Unsalted peanuts"}, {"id": "i9", "name": "japan szója", "qty": "200 g", "image": null, "enName": "Japanese soy sauce"}, {"id": "i10", "name": "maggi speciális, nem sárga flakonos", "qty": "50 g", "image": null, "enName": "Maggi special (not yellow bottle)"}, {"id": "i11", "name": "tengeri só tökmag fűszer nélkül pirítom. mogyoró 50%, mandula 15%, kesudió 15%, tökmag 20%", "qty": "20 g", "image": null, "enName": "Sea salt (toast pumpkin seeds without seasoning). Mix: 50% peanut, 15% almond, 15% cashew, 20% pumpkin seed."}]'::jsonb, '[]'::jsonb, TRUE) ON CONFLICT (id) DO NOTHING;